const POINTS: [number, number][] = [
  [1, 47],
  [2, 53],
  [3, 65],
  [4, 73],
  [5, 87],
];
const STOPS = [1, 5, 10, 50, 100, 300, 500, 1000];

const W = 320;
const H = 180;
const PAD_L = 26;
const PAD_B = 16;
const sx = (x: number) => PAD_L + (x / 6.5) * (W - PAD_L - 6);
const sy = (y: number) => (H - PAD_B) - (y / 110) * (H - PAD_B - 6);

const LW = 320;
const LH = 90;
const lx = (e: number) => 26 + (Math.log10(e) / 3) * (LW - 32);
const ly = (m: number) => (LH - 14) - (Math.log10(m) / Math.log10(1500)) * (LH - 20);

export function GradientDescentSimulator() {
  const [i, setI] = useState(HIST.length - 1);
  const [epoch, w, b, mse] = HIST[i];
  const pred6 = w * 6 + b;
  const lossPath = HIST.map(([e, , , m]) => `${lx(e).toFixed(1)},${ly(m).toFixed(1)}`).join(" ");

  return (
    <div data-figure className="not-prose panel my-6 p-4 sm:p-5">
      <div className="flex flex-wrap gap-1.5" role="group" aria-label="epoch 고르기">
        {STOPS.map((s) => {
          const idx = HIST.findIndex((r) => r[0] === s);
          return (
            <button
              key={s}
              type="button"
              onClick={() => setI(idx)}
              aria-pressed={epoch === s}
              className={`tap-feedback min-h-11 min-w-11 px-3 text-label font-semibold ${epoch === s ? "btn-action" : "btn"}`}
            >
              {s}
            </button>
          );
        })}
      </div>

      <label className="mt-3 flex flex-col gap-1">
        <span className="flex items-baseline justify-between text-label font-semibold">
          epoch <span className="font-mono tabular-nums">{epoch}</span>
        </span>
        <input
          type="range"
          min={0}
          max={HIST.length - 1}
          step={1}
          value={i}
          onChange={(e) => setI(Number(e.target.value))}
          className="h-11 w-full cursor-pointer touch-manipulation accent-accent dark:accent-accent-dark"
        />
      </label>

      <svg viewBox={`0 0 ${W} ${H}`} className="mt-2 h-auto w-full" role="img" aria-label={`epoch ${epoch}의 직선 y = ${w.toFixed(2)}x + ${b.toFixed(2)}와 실제 점수 5개`}>
        {[0, 20, 40, 60, 80, 100].map((t) => (
          <g key={t}>
            <line x1={PAD_L} x2={W - 6} y1={sy(t)} y2={sy(t)} className="stroke-line dark:stroke-line-dark" strokeWidth={0.5} />
            <text x={PAD_L - 3} y={sy(t) + 3} textAnchor="end" className="fill-muted dark:fill-muted-dark" fontSize={8}>
              {t}
            </text>
          </g>
        ))}
        {[1, 2, 3, 4, 5, 6].map((t) => (
          <text key={t} x={sx(t)} y={H - 4} textAnchor="middle" className="fill-muted dark:fill-muted-dark" fontSize={8}>
            {t}시간
          </text>
        ))}
        <line x1={sx(0)} x2={sx(6.5)} y1={sy(35)} y2={sy(10 * 6.5 + 35)} className="stroke-muted dark:stroke-muted-dark" strokeWidth={1} strokeDasharray="3 3" />
        {POINTS.map(([x, y]) => (
          <g key={x}>
            <line x1={sx(x)} x2={sx(x)} y1={sy(y)} y2={sy(w * x + b)} className="stroke-action dark:stroke-action-dark" strokeWidth={0.8} strokeDasharray="2 2" />
            <circle cx={sx(x)} cy={sy(y)} r={3} className="fill-accent dark:fill-accent-dark" />
          </g>
        ))}
        <line x1={sx(0)} x2={sx(6.5)} y1={sy(b)} y2={sy(w * 6.5 + b)} className="stroke-destructive dark:stroke-destructive-dark" strokeWidth={1.6} />
        <circle cx={sx(6)} cy={sy(pred6)} r={3} className="fill-none stroke-destructive dark:stroke-destructive-dark" strokeWidth={1.2} />
      </svg>
      <p className={`text-right text-label ${MUTED}`}>빨간 선이 지금 직선, 점선이 목표(10, 35), 점에서 선까지가 오차</p>

      <dl className="mt-3 grid grid-cols-2 gap-2 text-center sm:grid-cols-4" aria-live="polite">
        {[
          ["기울기 w", w.toFixed(2)],
          ["절편 b", b.toFixed(2)],
          ["MSE", mse.toFixed(2)],
          ["6시간 예측", `${pred6.toFixed(2)}점`],
        ].map(([k, v]) => (
          <div key={k} className="rounded-md bg-surface-2 px-2 py-2 dark:bg-surface-2-dark">
            <dt className={`text-label ${MUTED}`}>{k}</dt>
            <dd className="font-mono text-body font-bold tabular-nums">{v}</dd>
          </div>
        ))}
      </dl>

      <svg viewBox={`0 0 ${LW} ${LH}`} className="mt-3 h-auto w-full" role="img" aria-label="epoch에 따른 MSE 곡선">
        <polyline points={lossPath} fill="none" className="stroke-accent dark:stroke-accent-dark" strokeWidth={1.2} />
        <circle cx={lx(epoch)} cy={ly(mse)} r={3} className="fill-destructive dark:fill-destructive-dark" />
        {[1, 10, 100, 1000].map((t) => (
          <text key={t} x={lx(t)} y={LH - 2} textAnchor={t === 1000 ? "end" : "middle"} className="fill-muted dark:fill-muted-dark" fontSize={8}>
            {t}
          </text>
        ))}
        <text x={4} y={10} className="fill-muted dark:fill-muted-dark" fontSize={8}>
          MSE
        </text>
      </svg>
      <p className={`text-right text-label ${MUTED}`}>가로 epoch, 세로 MSE (둘 다 로그 눈금)</p>

      <p className="mt-2 text-label leading-relaxed">
        {epoch <= 10
          ? "처음에는 절편이 0 근처라 직선이 점들 아래에 깔려 있어요. 기울기부터 크게 올라가 17까지 갔다가, 절편이 따라 올라오면서 다시 내려와요."
          : epoch < 300
            ? "기울기는 조금씩 내려오고 절편은 올라가요. 한 epoch마다 점 5개를 하나씩 보며 직선을 오차가 줄어드는 쪽으로 살짝 옮겨요."
            : "목표 직선(기울기 10, 절편 35, MSE 3.2)에 거의 붙었어요. 1000번째에도 10.13, 34.74로 정답과 조금 달라요. 학습률이 일정하면 끝까지 조금씩 흔들려요."}
      </p>
    </div>
  );
}
